export function getCompletePraises(): PraiseItem[] {
  return ALL_PRAISES.map(p => ({
    ...p,
    text: p.text.normalize('NFC'),
    reference: p.reference.normalize('NFC')
  }));
}

export function getGroupedPages(): PageData[] {
  const praises = getCompletePraises();
  const pagesMap = new Map<number, PraiseItem[]>();

  praises.forEach(p => {
    if (!pagesMap.has(p.page)) {
      pagesMap.set(p.page, []);
    }
    pagesMap.get(p.page)!.push(p);
  });

  const pages: PageData[] = [];
  Array.from(pagesMap.keys()).sort((a, b) => a - b).forEach(pageNum => {
    const list = pagesMap.get(pageNum)!;
    const rawText = `பக்கம் ${pageNum}\n` + list.map(item => `${item.id}. ${item.text} (${item.reference})`).join('\n');
    pages.push({
      page: pageNum,
      title: `பக்கம் ${pageNum} (${list[0]?.id || ''} - ${list[list.length - 1]?.id || ''})`,
      rawText,
      praises: list
    });
  });

  return pages;
}
